import Foundation

/// Injects a generated `.sgmodule` into a proxy client's shared
/// AppGroup container (A9). The mechanism is Erosion-CN's
/// `AppGroupHubView.injectModuleIntoSurge` (Kianuni, GPL-3.0),
/// reimplemented for LilaShift's access helper: the module text is
/// generated by `ProxyRuleGenerator`, then written atomically into
/// the proxy client's own AppGroup container (the standard Surge
/// module directory, probed in order). Injection only targets
/// known proxy clients (Surge, Surge TestFlight, Shadowrocket,
/// Quantumult X, Loon, Stash) whose group container was detected
/// by `AppGroupDiscovery` — never an arbitrary container, never a
/// system path. The write is atomic and only touches the single
/// `LilaShift-AppleIntelligence-CN.sgmodule` file; the user must
/// still enable the module inside the proxy app itself, and
/// removing the file (or the module) fully reverses it. The
/// injector never writes outside the detected AppGroup container.
enum ProxyRuleInjector {
    enum InjectionError: LocalizedError {
        case accessDenied(String)
        case writeFailed(String)

        var errorDescription: String? {
            switch self {
            case .accessDenied(let message): return message
            case .writeFailed(let message): return message
            }
        }
    }

    /// Standard Surge module directories, probed in order (Erosion-CN).
    static let moduleSubpaths = [
        "Documents/Profiles/Modules",
        "Profiles/Modules",
        "Modules",
        "Documents",
    ]

    /// Writes the generated module into a detected proxy client's
    /// AppGroup container. Returns the file URL written. Throws when
    /// access cannot be granted or the write fails; the container is
    /// otherwise untouched.
    static func inject(content: String, into group: AppGroupContainer) throws -> URL {
        guard let data = content.data(using: .utf8), !data.isEmpty else {
            throw InjectionError.writeFailed(L("The generated module text is empty."))
        }
        guard AppGroupDiscovery.knownProxyGroups[group.groupID] != nil else {
            throw InjectionError.accessDenied(L("This AppGroup does not belong to a known proxy client."))
        }
        let fm = FileManager.default
        let grant = ContainerAccess.grantAccess(path: group.path, requireWrite: true)
        guard grant.granted else {
            throw InjectionError.accessDenied(grant.error ?? L("Could not get write access to the proxy client's shared container."))
        }
        defer { ContainerAccess.releaseAccess(path: group.path) }

        var targetDir = group.url.appendingPathComponent("Documents")
        for sub in moduleSubpaths {
            let candidate = group.url.appendingPathComponent(sub)
            var isDir: ObjCBool = false
            if fm.fileExists(atPath: candidate.path, isDirectory: &isDir), isDir.boolValue {
                targetDir = candidate
                break
            }
        }
        do {
            try fm.createDirectory(at: targetDir, withIntermediateDirectories: true)
            let dirGrant = ContainerAccess.grantAccess(path: targetDir.path, requireWrite: true)
            defer { ContainerAccess.releaseAccess(path: targetDir.path) }
            guard dirGrant.granted else {
                throw InjectionError.accessDenied(dirGrant.error ?? L("Could not get write access to the module directory."))
            }
            let targetFile = targetDir.appendingPathComponent(ProxyRuleFormat.surgeModule.fileName)
            try data.write(to: targetFile, options: .atomic)
            return targetFile
        } catch let error as InjectionError {
            throw error
        } catch {
            throw InjectionError.writeFailed(error.localizedDescription)
        }
    }

    /// Removes a previously injected module file. Returns `true`
    /// when a file was removed, `false` when none existed.
    static func removeInjectedModule(from group: AppGroupContainer) throws -> Bool {
        let fm = FileManager.default
        let grant = ContainerAccess.grantAccess(path: group.path, requireWrite: true)
        guard grant.granted else {
            throw InjectionError.accessDenied(grant.error ?? L("Could not get write access to the proxy client's shared container."))
        }
        defer { ContainerAccess.releaseAccess(path: group.path) }
        for sub in moduleSubpaths {
            let candidate = group.url.appendingPathComponent(sub)
                .appendingPathComponent(ProxyRuleFormat.surgeModule.fileName)
            if fm.fileExists(atPath: candidate.path) {
                try fm.removeItem(at: candidate)
                return true
            }
        }
        return false
    }
}
